import { buildMcq, buildNumerical } from './expandedHelpers.ts';
import type { CandidateQuestionInput } from './validationEngine.ts';

interface SpecB {
  id: string;
  chapter: string;
  topic: string;
  d: 'Easy' | 'Medium' | 'Hard';
  kind: 'MCQ' | 'Numerical' | 'MultiConcept';
  stem: string;
  ans: string;
  opts?: [string, string, string];
  sol: string;
  f: string;
}

function toCandidates(list: SpecB[]): CandidateQuestionInput[] {
  return list.map((s, idx) =>
    s.kind === 'Numerical'
      ? buildNumerical({
          externalId: s.id,
          subject: 'Physics',
          chapter: s.chapter,
          topic: s.topic,
          difficulty: s.d,
          questionText: s.stem,
          correctValue: s.ans,
          solution: s.sol,
          conceptTested: s.topic,
          formulaUsed: s.f,
          estimatedTimeSeconds: s.d === 'Easy' ? 50 : s.d === 'Medium' ? 75 : 105,
        })
      : buildMcq({
          externalId: s.id,
          subject: 'Physics',
          chapter: s.chapter,
          topic: s.topic,
          difficulty: s.d,
          questionType: s.kind === 'MultiConcept' ? 'MultiConcept' : 'MCQ',
          questionText: s.stem,
          correctOption: s.ans,
          correctExplanation: s.sol,
          distractors: (s.opts ?? []).map((o) => ({
            option: o,
            explanation: 'Does not satisfy the electromagnetic or modern physics equation.',
          })),
          solution: s.sol,
          conceptTested: s.topic,
          formulaUsed: s.f,
          estimatedTimeSeconds: s.d === 'Easy' ? 50 : s.d === 'Medium' ? 75 : 105,
          rotateIndex: idx,
        })
  );
}

